import{_ as n,o as a,c as p,a3 as t}from"./chunks/framework.bijRUqYl.js";const q=JSON.parse('{"title":"人力资源与招聘提示词模板","description":"HR 的 5 条提示词模板：JD 撰写、简历初筛、面试提纲、绩效面谈、制度文件。","frontmatter":{"title":"人力资源与招聘提示词模板","description":"HR 的 5 条提示词模板：JD 撰写、简历初筛、面试提纲、绩效面谈、制度文件。"},"headers":[],"relativePath":"community/prompts/人力资源与招聘.md","filePath":"community/prompts/人力资源与招聘.md"}'),e={name:"community/prompts/人力资源与招聘.md"};function l(o,s,i,c,u,r){return a(),p("div",null,[...s[0]||(s[0]=[t(`<h1 id="👥-人力资源与招聘-·-5-条提示词模板" tabindex="-1">👥 人力资源与招聘 · 5 条提示词模板 <a class="header-anchor" href="#👥-人力资源与招聘-·-5-条提示词模板" aria-label="Permalink to &quot;👥 人力资源与招聘 · 5 条提示词模板&quot;">​</a></h1><blockquote><p>HR 的活有个特点：<strong>每件事都要&quot;对得起所有人&quot;</strong>。 招聘要公平、面谈要有据、制度要合规。这几条模板都在帮你&quot;把依据摆出来&quot;。</p></blockquote><h2 id="本行三句话骨架" tabindex="-1">本行三句话骨架 <a class="header-anchor" href="#本行三句话骨架" aria-label="Permalink to &quot;本行三句话骨架&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>我是【公司规模 / 行业 / 我的岗位】，现在要处理【什么 HR 事项】。</span></span>
<span class="line"><span>帮我产出【JD / 提纲 / 面谈话术】，形式【…】。</span></span>
<span class="line"><span>规矩：不歧视、不打探隐私、不做没有依据的评价；涉及法律合规的地方请标出&quot;需确认&quot;。</span></span></code></pre></div><hr><h2 id="_1-·-jd-招聘启事-写清-我们要什么样的人-而不是堆福利" tabindex="-1">1 · JD（招聘启事）：写清&quot;我们要什么样的人&quot;，而不是堆福利 <a class="header-anchor" href="#_1-·-jd-招聘启事-写清-我们要什么样的人-而不是堆福利" aria-label="Permalink to &quot;1 · JD（招聘启事）：写清&quot;我们要什么样的人&quot;，而不是堆福利&quot;">​</a></h2><p><strong>什么时候用</strong>：招人难，收到的简历都不合适——往往不是人少，是 JD 没写清。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>岗位：【名称 / 汇报对象 / 团队规模 / 工作地点与方式】</span></span>
<span class="line"><span>这个岗位存在的真实原因：【为什么现在要招这个人，他解决了什么问题】</span></span>
<span class="line"><span>必须做的事（按重要性排）：【…】</span></span>
<span class="line"><span>必须具备的能力：【…（区分&quot;必须&quot;和&quot;加分&quot;）】</span></span>
<span class="line"><span>现在的团队情况：【…（招聘者要知道自己会面对什么）】</span></span>
<span class="line"><span>薪资范围与结构：【…】</span></span>
<span class="line"><span></span></span>
<span class="line"><span>帮我写 JD，要求：</span></span>
<span class="line"><span>① 前 3 行说清&quot;这个岗位每天在干什么&quot;（不要用&quot;负责XX工作&quot;这种空话）</span></span>
<span class="line"><span>② 分开写&quot;必须&quot;和&quot;加分&quot;，必须项不超过 5 条</span></span>
<span class="line"><span>③ 写清&quot;这个岗位不适合什么样的人&quot;（这条能帮你少收一半不合适的简历）</span></span>
<span class="line"><span>④ 面试流程写清楚（几轮、每轮多久、谁来面）</span></span>
<span class="line"><span>⑤ 结尾给一段&quot;我们这里真实的样子&quot;（不吹，包括难处）</span></span>
<span class="line"><span>规矩：不出现年龄、性别、婚育、籍贯等任何歧视性表述；不写&quot;抗压能力强&quot;这种含义不清的词——要写具体场景。</span></span></code></pre></div><p><strong>它给你</strong>：一份能筛掉不合适人的 JD。<strong>&quot;不适合什么样的人&quot;是这份 JD 最值钱的一段。</strong></p><hr><h2 id="_2-·-简历初筛-打分表-而不是感觉" tabindex="-1">2 · 简历初筛：打分表，而不是感觉 <a class="header-anchor" href="#_2-·-简历初筛-打分表-而不是感觉" aria-label="Permalink to &quot;2 · 简历初筛：打分表，而不是感觉&quot;">​</a></h2><p><strong>什么时候用</strong>：一天 50 份简历，筛到后面标准已经飘了。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>岗位要求（必须项 / 加分项）：</span></span>
<span class="line"><span>【1. … 2. … 3. …】</span></span>
<span class="line"><span></span></span>
<span class="line"><span>这批简历（去掉姓名、性别、年龄、照片后再给我）：</span></span>
<span class="line"><span>【候选人 A：粘贴工作经历与项目描述】</span></span>
<span class="line"><span>【候选人 B：…】</span></span>
<span class="line"><span>（依次）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>帮我输出一张筛选表：</span></span>
<span class="line"><span>| 代号 | 命中必须项 | 缺失必须项 | 加分项命中 | 硬性不符（如地点/证书） | 建议：约面 / 待定 / 不合适 | 理由（1 句） |</span></span>
<span class="line"><span>另外：</span></span>
<span class="line"><span>① 对&quot;建议约面&quot;的人，各写 2 个简历里说不清、面试必须追问的点</span></span>
<span class="line"><span>② 标出哪些人的简历有明显的&quot;夸大或前后矛盾&quot;（引用原文）</span></span>
<span class="line"><span>规矩：只看与岗位相关的能力与经历；不许基于性别、年龄、地域、学校档次做判断；不确定的写&quot;需面试确认&quot;。</span></span></code></pre></div><p><strong>它给你</strong>：一张可复核的表 + 追问点。<strong>&quot;用代号、去掉性别年龄&quot;这一步，你交给 AI 之前就该做。</strong></p><hr><h2 id="_3-·-面试提纲-含追问链" tabindex="-1">3 · 面试提纲（含追问链） <a class="header-anchor" href="#_3-·-面试提纲-含追问链" aria-label="Permalink to &quot;3 · 面试提纲（含追问链）&quot;">​</a></h2><p><strong>什么时候用</strong>：面试时凭感觉聊，聊完记不住细节，还容易问出&quot;你喜欢什么颜色&quot;这种无用问题。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>岗位：【…】。这次要重点考察：【能力 1 / 能力 2 / 稳定性 / 协作方式】</span></span>
<span class="line"><span>候选人背景（代号 + 简历要点）：【…】</span></span>
<span class="line"><span></span></span>
<span class="line"><span>帮我做一份 45 分钟面试提纲：</span></span>
<span class="line"><span>① 时间分配（开场 / 能力验证 / 反向提问 / 收尾）</span></span>
<span class="line"><span>② 每个考察点给 2 个问题，且每个问题带&quot;如果他说 A，我接下来问什么&quot;的追问链</span></span>
<span class="line"><span>③ 至少 2 个&quot;行为面试题&quot;（问过去具体做过什么，不问&quot;如果遇到……你会怎么做&quot;）</span></span>
<span class="line"><span>④ 3 个可以让我判断&quot;他在夸大&quot;的交叉验证问题</span></span>
<span class="line"><span>⑤ 一套我可以在面试中记录的表格模板（候选人的回答要点，当场填）</span></span>
<span class="line"><span>规矩：不问婚育、家庭、宗教、健康等与岗位无关的隐私；不给&quot;性格测试式&quot;的主观判断。</span></span></code></pre></div><p><strong>它给你</strong>：一份带追问链的提纲 + 现场记录表。</p><hr><h2 id="_4-·-绩效面谈-一对一反馈-说问题而不伤人" tabindex="-1">4 · 绩效面谈 / 一对一反馈（说问题而不伤人） <a class="header-anchor" href="#_4-·-绩效面谈-一对一反馈-说问题而不伤人" aria-label="Permalink to &quot;4 · 绩效面谈 / 一对一反馈（说问题而不伤人）&quot;">​</a></h2><p><strong>什么时候用</strong>：要跟下属谈一个不太好的评价，你拖了两周还没谈。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>对方：【岗位 / 在职多久 / 我跟他平时的关系】</span></span>
<span class="line"><span>我要反馈的事实（具体行为，不要评价词）：【…】</span></span>
<span class="line"><span>我的判断：【…】，我可能存在的偏见：【…（自己想一下）】</span></span>
<span class="line"><span>我这次谈的目标：【改善什么 / 还是只是告知】</span></span>
<span class="line"><span></span></span>
<span class="line"><span>帮我准备：</span></span>
<span class="line"><span>① 开场怎么说（先说清&quot;今天为什么聊这个&quot;，让对方有准备）</span></span>
<span class="line"><span>② 事实 → 影响 → 期待，三段式表达（每段给我可照说的句子）</span></span>
<span class="line"><span>③ 对方最可能的三种反应（不认 / 情绪化 / 沉默），各自我该怎么接</span></span>
<span class="line"><span>④ 我要问对方的 3 个问题（让他自己说出改进方案）</span></span>
<span class="line"><span>⑤ 收尾怎么说（明确下次什么时候看结果）</span></span>
<span class="line"><span>⑥ 我自己要注意的 3 句话（不要说的话）</span></span>
<span class="line"><span>规矩：只谈行为与结果，不做人格评价（不说&quot;态度差&quot;&quot;不积极&quot;）；不许编事实。</span></span></code></pre></div><p><strong>它给你</strong>：一份能照着说、也不至于失控的面谈稿。</p><hr><h2 id="_5-·-制度-通知-员工手册条款" tabindex="-1">5 · 制度 / 通知 / 员工手册条款 <a class="header-anchor" href="#_5-·-制度-通知-员工手册条款" aria-label="Permalink to &quot;5 · 制度 / 通知 / 员工手册条款&quot;">​</a></h2><p><strong>什么时候用</strong>：要发一份制度，怕写太狠没人情，又怕写太软管不住。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>我要写的制度：【考勤 / 报销 / 远程办公 / 请假 / 保密 …】</span></span>
<span class="line"><span>公司现状：【规模 / 行业 / 现在实际是怎么做的 / 有哪些历史遗留做法】</span></span>
<span class="line"><span>我必须解决的三个问题：【…】</span></span>
<span class="line"><span>地方规定或参考文件：【有就粘贴，没有就写&quot;无&quot;】</span></span>
<span class="line"><span></span></span>
<span class="line"><span>帮我写制度初稿，要求：</span></span>
<span class="line"><span>① 每条前面写清&quot;为什么要有这条&quot;（一句话，让员工理解出发点）</span></span>
<span class="line"><span>② 条款用&quot;应当/可以/不得&quot;这种明确表述，不用&quot;原则上&quot;&quot;尽量&quot;</span></span>
<span class="line"><span>③ 单独给我一张表：哪些条款可能与当地法规冲突、需要 HR 或律师确认</span></span>
<span class="line"><span>④ 附一个&quot;执行流程&quot;（谁审批、多久、怎么留痕）</span></span>
<span class="line"><span>⑤ 附一条 150 字以内的群通知版</span></span>
<span class="line"><span>规矩：不写法定之外的罚则；涉及扣钱、解雇、竞业的内容一律标&quot;需法律确认&quot;。</span></span></code></pre></div><p><strong>它给你</strong>：制度初稿 + 风险条款表 + 通知简版。</p><hr><h2 id="⚠️-这行的三条红线" tabindex="-1">⚠️ 这行的三条红线 <a class="header-anchor" href="#⚠️-这行的三条红线" aria-label="Permalink to &quot;⚠️ 这行的三条红线&quot;">​</a></h2><ol><li><strong>不许用 AI 做&quot;是否录用&quot;的最终判断</strong>：让它帮你排序、标出席、生成追问点，<strong>但决定必须由人做</strong>，并且能说明依据。</li><li><strong>把&quot;不该看的信息&quot;先去掉</strong>：性别、年龄、婚育、照片、籍贯、民族、健康状况——这些在交给 AI 之前就该删掉，不是让 AI&quot;别看&quot;。</li><li><strong>涉及解除、扣薪、竞业的文本，必须法律确认</strong>：AI 写的只能算草稿。</li></ol><hr><p><strong>目录</strong>：<a href="/MoMAWork-/community/prompts/">← 回到行业提示词模板库</a> ｜ 下一个行业 → <strong><a href="/MoMAWork-/community/prompts/自媒体与内容创作.html">自媒体与内容创作</a></strong></p>`,34)])])}const d=n(e,[["render",l]]);export{q as __pageData,d as default};
